type FileInfo struct {
 	… Functions []FuncDef; Types []TypeDef
+	Values     []ValueDef `json:"values,omitempty"`
 }

+// ValueDef is ONE package-level var or const NAME (not one per spec:
+// `var a, b = f()` is two addressable symbols and a lookup for b must find it).
+type ValueDef struct {
+	Name, Kind, Doc, Type string   // Kind ∈ {var, const}; Type empty when inferred
+	Exported              bool
+	StartLine, EndLine    int
+}

-if d.Tok == token.TYPE { … }
+switch d.Tok {
+case token.TYPE:  … unchanged …
+case token.VAR, token.CONST:
+	for _, spec := range d.Specs {
+		if vs, ok := spec.(*ast.ValueSpec); ok {
+			fi.Values = append(fi.Values, valueDefs(fset, d, vs)...)
+		}
+	}
+}

+func valueDefs(fset, d *ast.GenDecl, vs *ast.ValueSpec) []ValueDef {
+	start, end := vs.Pos(), vs.End()
+	if !d.Lparen.IsValid() { start, end = d.Pos(), d.End() }   // lone decl: keep the keyword
+	… doc from spec, falling back to decl; skip n.Name == "_" …
+}

+for _, vd := range f.Values {
+	sig := vd.Type
+	if sig != "" { sig = vd.Kind + " " + vd.Name + " " + sig }
+	content := composeSymbolContent(vd.Kind, vd.Name, sig, vd.Doc, f.Path)
+	rows = append(rows, symbolRow{
+		path: f.Path, symbol: vd.Name, kind: vd.Kind,
+		signature: sig, doc: vd.Doc, content: content,
+		hash: sha256hex(content), lineStart: vd.StartLine, lineEnd: vd.EndLine,
+		body: slice(vd.StartLine, vd.EndLine),   // the body IS the evidence for a value
+	})
+}
